from rcb_client import Robot
import numpy as np
r=Robot();o=r.get_obs(depth=True);c='robot_r1:right_realsense_link:Camera:0';D=o.last_depth[c];E=np.vstack([o.meta['cameras'][c]['extrinsic_cv'],[0,0,0,1]]);Ei=np.linalg.inv(E);K=np.array(o.meta['cameras'][c]['intrinsic_cv']);
for uv in [(50,25),(70,35),(90,45),(80,60),(100,65),(110,75),(130,90)]:
 u,v=uv;d=float(D[v,u]);pc=np.array([(u-K[0,2])*d/K[0,0],(v-K[1,2])*d/K[1,1],d,1]);print(uv,round(d,3),np.round((Ei@pc)[:3],3))
print('extr',np.round(E,2));
